        while heap:
            dist, c_node = heapq.heappop(heap)
            # 모든 노드 검색
            for n_node, weight in dic[c_node]:
                # 연결된 노드 거르기
                if weight > 0 :
                    n_dist = dist + weight
                    if n_dist < distances[n_node]:
                        distances[n_node] = n_dist
                        heapq.heappush(heap, (n_dist, n_node))
        return distances

    temp = dijkstra()

    for x in range(len(temp)):
        if temp[x] <= K:
            answer += 1
    return answer

